{"action":"write_file","path":"toposort.js","content":"'use strict';

function topoSort(graph) {
  if (graph === null || typeof graph !== 'object' || Array.isArray(graph)) {
    throw new TypeError('graph must be a plain object');
  }

  // Check prototype to ensure it's a plain object (or object literal / created without prototype or plain)
  // Usually checking proto or constructor or Object.prototype.toString.call(graph) === '[object Object]'
  const proto = Object.getPrototypeOf(graph);
  if (proto !== Object.prototype && proto !== null) {
    throw new TypeError('graph must be a plain object');
  }

  // Collect all nodes and validate dependency lists
  const allNodes = new Set();
  const graphCopy = Object.create(null);

  for (const [node, deps] of Object.entries(graph)) {
    if (!Array.isArray(deps)) {
      throw new TypeError('dependency list must be an array of strings');
    }
    for (const d of deps) {
      if (typeof d !== 'string') {
        throw new TypeError('dependency list must contain strings');
      }
      allNodes.add(d);
    }
    allNodes.add(node);
    // Deduplicate deps and filter/copy
    graphCopy[node] = Array.from(new Set(deps));
  }

  // For nodes that only appear inside a dependency list (i.e. not keys in graph), they have 0 dependencies.
  for (const node of allNodes) {
    if (!(node in graphCopy)) {
      graphCopy[node] = [];
    }
  }

  // We need to output nodes deterministically:
  // "repeatedly output the node that is smallest by < string comparison among all nodes whose dependencies have already been output"
  // Let's implement Kahn's algorithm or a simulation with a priority queue / sorted set, or greedy selection.
  // Since N might be small or moderate, we can track which nodes have been output.
  // A node's dependencies have all been output if every dependency of that node is in the output set.

  const output = [];
  const outputSet = new Set();
  const remaining = new Set(allNodes);

  while (remaining.size > 0) {
    // Find all nodes in remaining whose dependencies are all in outputSet
    const ready = [];
    for (const node of remaining) {
      const deps = graphCopy[node];
      let readyDeps = true;
      for (const d of deps) {
        if (!outputSet.has(d)) {
          readyDeps = false;
          break;
        }
      }
      if (readyDeps) {
        ready.push(node);
      }
    }

    if (ready.length === 0) {
      const err = new Error('Cycle detected');
      err.code = 'CYCLE';
      throw err;
    }

    // Sort ready nodes lexicographically (smallest by < string comparison)
    ready.sort();

    // Pick the smallest
    const next = ready[0];
    remaining.delete(next);
    outputSet.add(next);
    output.push(next);
  }

  return output;
}

module.exports = { topoSort };
