{"action":"write_file","path":"toposort.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { topoSort } = require('./toposort');

test('dependencies come first', () => {
  assert.deepEqual(topoSort({ app: ['lib', 'util'], lib: ['util'], util: [] }), ['util', 'lib', 'app']);
});

test('a cycle is reported', () => {
  assert.throws(() => topoSort({ a: ['b'], b: ['a'] }), (e) => e.code === 'CYCLE');
});

test('self cycle is reported', () => {
  assert.throws(() => topoSort({ a: ['a'] }), (e) => e.code === 'CYCLE');
});

test('empty graph', () => {
  assert.deepEqual(topoSort({}), []);
});

test('alphabetical tie breaking', () => {
  assert.deepEqual(topoSort({ b: ['d'], a: ['d'], d: [], c: [] }), ['c', 'd', 'a', 'b']);
});

test('invalid inputs throw TypeError', () => {
  assert.throws(() => topoSort(null), TypeError);
  assert.throws(() => topoSort([]), TypeError);
  assert.throws(() => topoSort('graph'), TypeError);
  assert.throws(() => topoSort(Object.create({})), TypeError);
  assert.throws(() => topoSort({ a: 'not-array' }), TypeError);
  assert.throws(() => topoSort({ a: [123] }), TypeError);
});
"}
